class SubmitLoanRequestModule_AutoGenerated {
  /*if the current loan request exists,
   *and it has the requested CA history and has the request credit history,
   *the current loan request' credit score should be 100 and,
   *the loan request status should be submitted then give the result the current loan request's credit score
   *the current loan request requested ca history should be it*/
  calculateScore(): number {
    /*Definition Start*/
    let currentLoanRequest: LoanRequest = l({
      logic: () => this.CurrentLoanRequest,
      description: "self.CurrentLoanRequest",
    }).build().pass;
    let ca: CheckingAccount = l({
      logic: () => currentLoanRequest.RequestedCAHistory,
      description: "currentLoanRequest.RequestedCAHistory",
    }).build().pass;
    let ch: CreditHistory = l({
      logic: () => currentLoanRequest.RequestedCreditHistory,
      description: "currentLoanRequest.RequestedCreditHistory",
    }).build().pass;
    let cs: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => currentLoanRequest.CreditScore === 100,
            description: "currentLoanRequest.CreditScore=100",
          }),
        description: "currentLoanRequest.CreditScore=100",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
    let statusSubmitted: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () =>
              currentLoanRequest.Status === LoanRequestStatus.SUBMITTED,
            description:
              "currentLoanRequest.Status=LoanRequestStatus::SUBMITTED",
          }),
        description: "currentLoanRequest.Status=LoanRequestStatus::SUBMITTED",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsUndefined(currentLoanRequest) === false,
        description: "currentLoanRequest.oclIsUndefined()=false",
      })
        .and({
          logic: () => StandardOPs.oclIsUndefined(ca) === false,
          description: "ca.oclIsUndefined()=false",
        })
        .and({
          logic: () => StandardOPs.oclIsUndefined(ch) === false,
          description: "ch.oclIsUndefined()=false",
        })
        .and({
          logic: () => cs === true,
          description: "cs=true",
        })
        .and({
          logic: () => statusSubmitted === true,
          description: "statusSubmitted=true",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    return l({
      execute: () => currentLoanRequest.CreditScore,
      description: "result=currentLoanRequest.CreditScore",
    })
      .and({
        execute: () => (currentLoanRequest.RequestedCAHistory = ca),
        description: "currentLoanRequest.RequestedCAHistory=ca",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { SubmitLoanRequestModule_AutoGenerated };

